    if (!survive &&
            (wizard() || discover()) &&
            how <= NHC.GENOCIDED &&
            !(cptr.ldI32o(program_state, $sinfo_done_hup) &&
                (cptr.stI64o(
                    gd,
                    $instance_globals_d_done_seq,
                    cptr.ldI64o(gd, $instance_globals_d_done_seq) + 1n
                )) -
                    (1n) ==
                    cptr.ldI64o(gh, $instance_globals_h_hero_seq)) &&
            !(yield* paranoid_query(
                schar((((cptr.ldI32o(flags, $flag_paranoia_bits) & NHM.PARANOID_DIE) >>> 0) != 0)),
                __s_die__2
            ))) {
        (yield* pline(__s_ok_so_you_don_t_s, (how == NHC.CHOKING) ? __s_choke : __s_die__3));
        cptr.stI32o(iflags, $instance_flags_last_msg, NHC.PLNMSG_OK_DONT_DIE);
        (yield* savelife(how));
        survive = 1;
    }

    if (survive) {
        cptr.st1o2(svk, 0, 1, $kinfo_name, 0);
        cptr.stI32o(svk, $kinfo_format, NHM.KILLED_BY_AN);  /* reset to 0 */
        return;
    }
    (yield* really_done(how));
    /*NOTREACHED*/
