        (yield* Y.icall(destroy_nhwindow()(WIN_MAP.v))), WIN_MAP.v = -1;
        if (WIN_STATUS.v != -1)
            (yield* Y.icall(destroy_nhwindow()(WIN_STATUS.v))), WIN_STATUS.v = -1;
        (yield* Y.icall(destroy_nhwindow()(WIN_MESSAGE.v))), WIN_MESSAGE.v = -1;

